const fs=require("fs"),path=require("path"),crypto=require("crypto");
const dir="C:/Users/凯瑞/Desktop/SKILL调试文件/run-trace-卷纲层-20260918-224640-deep";
const rt=JSON.parse(fs.readFileSync(path.join(dir,"run-trace.json"),"utf8"));
const ex=JSON.parse(fs.readFileSync(path.join(dir,"export.json"),"utf8"));
function diff(a,b,p="",out=[]){if(Array.isArray(a)&&Array.isArray(b)){if(a.length!==b.length)out.push(p+" length "+a.length+"!="+b.length);for(let i=0;i<Math.min(a.length,b.length);i++)diff(a[i],b[i],p+"["+i+"]",out);}else if(a&&b&&typeof a==="object"&&typeof b==="object"){const ks=new Set([...Object.keys(a),...Object.keys(b)]);for(const k of ks)diff(a[k],b[k],p+"."+k,out);}else if(JSON.stringify(a)!==JSON.stringify(b))out.push(p+": "+JSON.stringify(a)+" != "+JSON.stringify(b));return out}
const d=diff(rt,ex);console.log("DIFF_COUNT",d.length);for(const x of d.slice(0,80))console.log(x);
console.log("\nHASH_CHECK");
let bad=0;
for(const p of rt.payloads){const f=path.join(dir,"payloads",p.file);if(!fs.existsSync(f)){console.log("MISSING",p.file);bad++;continue}const buf=fs.readFileSync(f);const h=crypto.createHash("sha256").update(buf).digest("hex");const n=buf.length;if(h!==p.sha256||n!==p.bytes){console.log("MISMATCH",p.file,{expected:p.bytes+" / "+p.sha256,actual:n+" / "+h});bad++}}
console.log("hashBad",bad,"payloads",rt.payloads.length);
console.log("\nREFS");
function walk(o,p="",refs=[]){if(!o||typeof o!=="object")return refs;if(typeof o.payloadRef==="string")refs.push(p+".payloadRef="+o.payloadRef);if(typeof o.ref==="string"&&o.ref.startsWith("payload-"))refs.push(p+".ref="+o.ref);if(typeof o.inputRef==="string")refs.push(p+".inputRef="+o.inputRef);if(typeof o.outputRef==="string")refs.push(p+".outputRef="+o.outputRef);if(typeof o.responseTextPayloadRef==="string")refs.push(p+".responseTextPayloadRef="+o.responseTextPayloadRef);for(const [k,v] of Object.entries(o))walk(v,p+"."+k,refs);return refs}
const refs=walk(rt);const ids=new Set(rt.payloads.map(p=>p.id));console.log("refs",refs.length,"unresolved",[...new Set(refs)].filter(r=>{const m=r.match(/(?:payloadRef|ref|inputRef|outputRef|responseTextPayloadRef)=(payload-\d+)/);return m&&!ids.has(m[1])}));
