import {writeFile} from 'node:fs/promises';
import {Readable} from 'node:stream';
const repo='BelleGroup/train_1M_CN';
const file='Belle_open_source_1M.json';
const url='https://hf-mirror.com/datasets/'+repo+'/resolve/main/'+file;
const r=await fetch(url);
if(!r.ok){console.error('HTTP',r.status);process.exit(1)}
const nodeStream=Readable.fromWeb(r.body);
const decoder=new TextDecoder('utf-8');
let buffer='';
let count=0; const samples=[]; let done=false;
nodeStream.on('data',chunk=>{
 if(done) return;
 buffer+=decoder.decode(chunk,{stream:true});
 let idx;
 while((idx=buffer.indexOf('\n'))>=0){
  const line=buffer.slice(0,idx).trim();
  buffer=buffer.slice(idx+1);
  if(!line) continue;
  try{ samples.push(JSON.parse(line)); count++; }catch{}
  if(count>=3000){done=true; break;}
 }
});
nodeStream.on('end',()=>console.log('stream end',count));
nodeStream.on('error',e=>{console.error(e);process.exit(1)});
setInterval(()=>{
 if(done){
  clearInterval();
  writeFile('_tmp_research/belle-train-cn-sample.json',JSON.stringify({repo,file,sampleCount:count,items:samples},null,2),'utf8').then(()=>console.log('saved',count));
  process.exit(0);
 }
},100);
