$script = @'
import fs from 'node:fs'

const out = []
const headers = {
  'Accept': 'application/vnd.github+json',
  'User-Agent': 'novel-workshop-research'
}

const githubQueries = [
  'semantic router intent classification',
  'sentence transformers intent classification',
  'transformers.js embeddings browser',
  'bge-small-zh embeddings onnx',
  'm3e chinese embedding onnx',
  'intent classification confidence calibration',
  'rasa nlu intent confidence fallback',
  'llm intent router tool use',
  'langchain semantic routing',
  'active learning intent classification',
]

const hfQueries = [
  'BAAI bge small zh',
  'moka embeddings m3e small',
  'shibing624 text2vec base chinese',
  'GanymedeNil text2vec-large-chinese',
  ' Xenova bge-small-zh',
  'sentence transformers chinese',
  'intent classification dataset chinese',
  'semantic router',
  'onnx text classification',
  'embedding model quantized'
]

async function getJson(url) {
  const res = await fetch(url, { headers })
  if (!res.ok) throw new Error(`${res.status} ${url}`)
  return res.json()
}

for (let i = 0; i < githubQueries.length; i++) {
  const q = githubQueries[i]
  const url = `https://api.github.com/search/repositories?q=${encodeURIComponent(q)}&sort=stars&order=desc&per_page=10`
  try {
    const data = await getJson(url)
    out.push({
      round: i + 1,
      kind: 'github',
      query: q,
      url,
      total: data.total_count,
      items: (data.items || []).map(x => ({
        id: x.full_name,
        stars: x.stargazers_count,
        description: x.description,
        url: x.html_url,
        updated: x.updated_at
      }))
    })
  } catch (e) {
    out.push({ round: i + 1, kind: 'github', query: q, url, error: e.message })
  }
}

for (let i = 0; i < hfQueries.length; i++) {
  const q = hfQueries[i].trim()
  const url = `https://hf-mirror.com/api/models?search=${encodeURIComponent(q)}&limit=10`
  try {
    const data = await getJson(url)
    out.push({
      round: i + 11,
      kind: 'huggingface',
      query: q,
      url,
      total: Array.isArray(data) ? data.length : 0,
      items: (data || []).map(x => ({
        id: x.id,
        downloads: x.downloads,
        likes: x.likes,
        tags: x.tags
      }))
    })
  } catch (e) {
    out.push({ round: i + 11, kind: 'huggingface', query: q, url, error: e.message })
  }
}

fs.writeFileSync('_audit/RESEARCH_2026-09-20_intent-router-maturity-search.json', JSON.stringify({
  searchedAt: new Date().toISOString(),
  queryCount: out.length,
  results: out
}, null, 2))
console.log(`rounds=${out.length}`)
for (const r of out) {
  console.log(`${r.round}. [${r.kind}] ${r.query} total=${r.total ?? 'ERR'} ${r.error ? 'ERROR=' + r.error : ''}`)
  for (const item of (r.items || []).slice(0, 3)) {
    console.log(`   ${item.id}${item.stars !== undefined ? ' stars=' + item.stars : ' downloads=' + item.downloads}`)
  }
}
