import fs from 'node:fs'
import path from 'node:path'
const data = JSON.parse(fs.readFileSync(path.join(process.cwd(), '_audit/intent-routing-v6-phase5-calibration.json'), 'utf8'))
const strategy='centroid'
const thresholds={analyze:0.30,edit:0.34,generate:0.34,discuss:0.30}
const ambiguity={analyze:0.06,edit:0.08,generate:0.08,discuss:0.06}
const oos=0.24
const scopeCategories=['outlineDomainTerms','settingDomainTerms','volumeDomainTerms','chapterDomainTerms','editorDomainTerms']
const rows=[]
for (const [index,s] of data.scoredSamples.entries()) {
  if (s.expected==='no_match') continue
  if (s.sync.kind==='matched') { rows.push({index,...s,actual:s.sync.intent,layer:'sync'}); continue }
  if (s.sync.kind==='ambiguous') { rows.push({index,...s,actual:'ambiguous',layer:'sync'}); continue }
  if (!s.scores) { rows.push({index,...s,actual:'no_match',layer:'sync-no-score'}); continue }
  // scope gate is unavailable here; mark unknown, route using best score.
  const ranked=Object.entries(s.scores).map(([intent,v])=>[intent,v[strategy]]).sort((a,b)=>b[1]-a[1])
  const [bestIntent,bestScore]=ranked[0]
  const second=ranked[1]
  let actual, layer
  if (bestScore < oos) { actual='out-of-scope'; layer='oos' }
  else if (bestScore < thresholds[bestIntent]) { actual='no_match'; layer='threshold' }
  else if (second && bestScore-second[1] < ambiguity[bestIntent]) { actual='ambiguous'; layer='margin' }
  else { actual=bestIntent; layer='classified' }
  rows.push({index,...s,actual,layer,bestIntent,bestScore:Number(bestScore.toFixed(4)),secondIntent:second?.[0],secondScore:Number(second?.[1].toFixed(4))})
}
const failures=rows.filter(r=>['no_match','ambiguous','out-of-scope'].includes(r.actual))
const byReason={}
for(const r of failures){const key=`${r.layer}:${r.actual}`;byReason[key]=(byReason[key]||0)+1}
