  return na-nb;
});
for (const file of files) {
  let obj;
  try { obj = JSON.parse(fs.readFileSync(path.join(dir,file),'utf8')); } catch { continue; }
  const kind = file.includes('request') ? 'REQ' : file.includes('response') ? 'RES' : file.includes('tool-input') ? 'TIN' : file.includes('tool-result') ? 'TRT' : 'STR';
  if (kind === 'REQ') {
