    const status = obj.status || obj.statusCode || '';
    console.log(`${file}\tchars=${inputChars}\tstart=${started}\tend=${finished}\tstatus=${status}\ttoplevel=${j.length}`);
  } else if (kind === 'RES') {
    const text = typeof obj.content === 'string' ? obj.content : typeof obj.text === 'string' ? obj.text : '';
    const started = obj.startedAt || obj.startTime || obj.timestamp || obj.createdAt || '';
    const finished = obj.finishedAt || obj.endTime || obj.completedAt || '';
    console.log(`${file}\tchars=${text.length}\tstart=${started}\tend=${finished}`);
  } else if (kind === 'TIN' || kind === 'TRT') {
    const name = obj.name || obj.toolName || obj.tool_name || '';
    const text = obj.result && typeof obj.result.content === 'string' ? obj.result.content : obj.resultText || obj.content || '';
    const status = obj.status || (obj.result && obj.result.status) || '';
    console.log(`${file}\ttool=${name}\tstatus=${status}\tchars=${String(text).length}`);
  }
}
