import ctypes, sys, time

user32 = ctypes.windll.user32

def child_windows(hwnd):
    result = []
    cb = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)(lambda h, _: result.append(h) or True)
    user32.EnumChildWindows(hwnd, cb, 0)
    return result

def cls_name(hwnd):
    buf = ctypes.create_unicode_buffer(256)
    user32.GetClassNameW(hwnd, buf, 256)
    return buf.value

def text(hwnd):
    n = user32.GetWindowTextLengthW(hwnd)
    buf = ctypes.create_unicode_buffer(n + 1)
    user32.GetWindowTextW(hwnd, buf, n + 1)
    return buf.value

def find_save_dialog():
    top = []
    user32.EnumWindows(ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)(lambda h, _: top.append(h) or True), 0)
    for hwnd in top:
        if not user32.IsWindowVisible(hwnd):
            continue
        if cls_name(hwnd) != '#32770':
            continue
        for child in child_windows(hwnd):
            if cls_name(child) == 'Edit':
                return hwnd
    return None

def find_save_button(dialog):
    for child in child_windows(dialog):
        btn = text(child).replace('&', '')
        if '保存' in btn or 'Save' in btn or '另存' in btn:
            return child
    return None

def click(btn):
    import time
    user32.SendMessageW(btn, 0x00F5, 0, 0)
    time.sleep(0.1)
    user32.PostMessageW(btn, 0x0201, 1, 0)
    user32.PostMessageW(btn, 0x0202, 0, 0)

def main():
    target = sys.argv[1]
    deadline = time.time() + 30
    while time.time() < deadline:
        dlg = find_save_dialog()
        if dlg:
            user32.SetForegroundWindow(dlg)
            for child in child_windows(dlg):
                if cls_name(child) == 'Edit':
                    user32.SetFocus(child)
                    user32.SendMessageW(child, 0x000C, 0, target)
                    time.sleep(0.2)
                    break
            save_btn = find_save_button(dlg)
            if save_btn:
                click(save_btn)
            else:
                user32.SendMessageW(dlg, 0x0100, 0x0D, 0)
                user32.SendMessageW(dlg, 0x0101, 0x0D, 0)
            time.sleep(0.5)
            sys.exit(0)
        time.sleep(0.1)
    sys.exit(2)

if __name__ == '__main__':
    main()
