const WebSocket = require('ws');
async function main() {
  const res = await fetch('http://127.0.0.1:9227/json');
  const pages = await res.json();
  const page = pages.find(p => p.url.includes('index.html'));
  if (!page) { console.error('NO PAGE'); process.exit(1); }
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise(r => ws.on('open', r));
  const send = (method, params = {}) => new Promise((resolve) => {
    const id = Math.random().toString(36);
    ws.send(JSON.stringify({ id, method, params }));
    ws.on('message', function handler(data) {
      const msg = JSON.parse(data);
      if (msg.id === id) { ws.off('message', handler); resolve(msg.result); }
    });
  });
  const expr = `(() => {
    const app = document.querySelector('#app').__vue_app__;
    const pinia = app.config.globalProperties.$pinia;
    const projectStore = pinia._s.get('project');
    return JSON.stringify({
      currentProjectId: projectStore.currentProjectId,
      volumesLength: projectStore.volumes.length,
      outlineTextLength: (projectStore.outlineText || '').length,
      outlineLocked: projectStore.outlineLocked
    });
  })()`;
  const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true });
  console.log(r.result.value);
  ws.close();
  process.exit(0);
}
main().catch(e => { console.error(e.message); process.exit(1); });
