const CDP_PORT = 9227
async function main() {
  const pages = await (await fetch(`http://127.0.0.1:${CDP_PORT}/json/list`)).json()
  const page = pages.find(item => item.type === 'page')
  if (!page) throw new Error('CDP page not found')
  const ws = new WebSocket(page.webSocketDebuggerUrl)
  let id = 0; const pending = new Map()
  ws.onmessage = event => { const m = JSON.parse(event.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id) } }
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject })
  const send = (method, params = {}) => new Promise((resolve, reject) => { const requestId = ++id; pending.set(requestId, resolve); ws.send(JSON.stringify({ id: requestId, method, params })); setTimeout(() => reject(new Error(`CDP timeout: ${method}`)), 30000) })
  const expression = `(async () => {
    const read = key => window.electronAPI.storageRead(key)
    const project = await read('wa_project_default')
    const ctx = await read('wa_ctx_default')
    const memories = project?.memories?.items || []
    const first = memories[0] || null
    const sessions = ctx?.sessions || []
    const main = sessions.find(s => s.id === 'main__generate__default')
    const injected = main?.messages?.some(m => first && String(m.content || '').includes(String(first.key || '')))
    const visible = [...document.querySelectorAll('*')].filter(el => { const r = el.getBoundingClientRect(); const s = getComputedStyle(el); return r.width > 0 && r.height > 0 && (el.scrollWidth > el.clientWidth + 1 || el.scrollHeight > el.clientHeight + 1) && s.overflow !== 'hidden' }).slice(0, 40).map(el => ({ tag: el.tagName, id: el.id, cls: String(el.className).slice(0, 100), scrollWidth: el.scrollWidth, clientWidth: el.clientWidth, scrollHeight: el.scrollHeight, clientHeight: el.clientHeight }))
    return { url: location.href, projectId: project?.id, projectName: project?.name, memoryCount: memories.length, firstMemory: first ? { key: first.key, content: String(first.content || '').slice(0, 160) } : null, contextSessions: sessions.length, mainContextMessages: main?.messages?.length || 0, memoryKeyFoundInContext: Boolean(injected), visibleOverflowCandidates: visible }
  })()`
  const result = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })
  if (result.exceptionDetails) throw new Error(JSON.stringify(result.exceptionDetails))
  console.log(JSON.stringify(result.result.result.value, null, 2)); ws.close()
}
main().catch(e => { console.error(e); process.exit(1) })
