$script = @'
const WebSocket = require('ws');
const fs = require('fs');
const target = process.argv[2];
const scriptPath = process.argv[3];
const outputPath = process.argv[4];
const ws = new WebSocket(target, { maxPayload: 512 * 1024 * 1024 });
let id = 0;
const pending = new Map();
function send(method, params) {
  return new Promise((resolve, reject) => {
    const messageId = ++id;
    pending.set(messageId, { resolve, reject });
    ws.send(JSON.stringify({ id: messageId, method, params }));
  });
}
ws.on('message', raw => {
  const message = JSON.parse(raw.toString());
  if (message.id && pending.has(message.id)) {
    const entry = pending.get(message.id);
    pending.delete(message.id);
    if (message.error) entry.reject(new Error(message.error.message));
    else entry.resolve(message.result);
  }
});
ws.on('open', async () => {
  try {
    const expression = fs.readFileSync(scriptPath, 'utf8');
    const result = await send('Runtime.evaluate', {
      expression,
      awaitPromise: true,
      returnByValue: true,
      userGesture: true
    });
    fs.writeFileSync(outputPath, JSON.stringify(result, null, 2));
    console.log('CDP_OK');
  } catch (error) {
    fs.writeFileSync(outputPath, JSON.stringify({ error: String(error) }, null, 2));
    console.error('CDP_FAIL', error);
    process.exitCode = 1;
  } finally {
    ws.close();
  }
});
ws.on('error', error => {
  console.error('WS_ERROR', error);
  process.exit(1);
});
