const crypto = require('crypto');

const target = process.argv[2];
const scriptPath = process.argv[3];
const outputPath = process.argv[4];
const url = new URL(target);

function rawSend(socket, payload) {
  const data = Buffer.from(payload);
  const length = data.length;
  let header;
  if (length < 126) {
    header = Buffer.from([0x81, length]);
  } else if (length < 65536) {
    header = Buffer.alloc(4);
    header[0] = 0x81; header[1] = 126;
    header.writeUInt16BE(length, 2);
  } else {
    header = Buffer.alloc(10);
    header[0] = 0x81; header[1] = 127;
    header.writeBigUInt64BE(BigInt(length), 2);
  }
  socket.write(Buffer.concat([header, data]));
}

const request = http.request({
  hostname: url.hostname,
  port: url.port,
  path: url.pathname + url.search,
  headers: {
    Connection: 'Upgrade',
    Upgrade: 'websocket',
    'Sec-WebSocket-Key': crypto.randomBytes(16).toString('base64'),
    'Sec-WebSocket-Version': '13'
  }
});

request.on('upgrade', (response, socket, head) => {
  let buffer = head ? Buffer.from(head) : Buffer.alloc(0);
  let text = '';
  let messageCallback = null;

  function parseFrames() {
    while (true) {
      if (buffer.length < 2) return;
      const second = buffer[1];
      const masked = Boolean(second & 0x80);
      let length = second & 0x7f;
      let offset = 2;
      if (length === 126) {
        if (buffer.length < 4) return;
        length = buffer.readUInt16BE(2); offset = 4;
      } else if (length === 127) {
        if (buffer.length < 10) return;
        length = Number(buffer.readBigUInt64BE(2)); offset = 10;
      }
      const maskLength = masked ? 4 : 0;
      if (buffer.length < offset + maskLength + length) return;
      const mask = masked ? buffer.subarray(offset, offset + 4) : null;
      let payload = buffer.subarray(offset + maskLength, offset + maskLength + length);
      if (mask) payload = Buffer.from(payload.map((byte, index) => byte ^ mask[index % 4]));
      const opcode = buffer[0] & 0x0f;
      buffer = buffer.subarray(offset + maskLength + length);
      if (opcode === 1) {
        text += payload.toString('utf8');
        if (messageCallback) {
          const callback = messageCallback;
          messageCallback = null;
          callback(text);
          text = '';
        }
      }
    }
  }

  socket.on('data', data => {
    buffer = Buffer.concat([buffer, data]);
    parseFrames();
  });

  function waitForMessage() {
    return new Promise(resolve => {
      if (text) {
        const value = text;
        text = '';
        resolve(value);
        return;
      }
      messageCallback = resolve;
    });
  }

