    try {
      const expression = fs.readFileSync(scriptPath, 'utf8');
      rawSend(socket, JSON.stringify({ id: 1, method: 'Runtime.evaluate', params: { expression, awaitPromise: true, returnByValue: true, userGesture: true } }));
