function New-WebSocket([string]$url) {
  $socket = [System.Net.WebSockets.ClientWebSocket]::new()
  $socket.ConnectAsync([Uri]$url, [System.Threading.CancellationToken]::None).GetAwaiter().GetResult()
  return $socket
}

function Send-Command($socket, [int]$id, [string]$method, $params) {
  $payload = @{ id = $id; method = $method; params = $params } | ConvertTo-Json -Depth 20 -Compress
  $bytes = [System.Text.Encoding]::UTF8.GetBytes($payload)
  $maskKey = [byte[]](1,2,3,4)
  $frame = [byte[]]::new($bytes.Length + 14)
  $frame[0] = 0x81
  if ($bytes.Length -le 125) { $frame[1] = [byte](0x80 -bor $bytes.Length); $offset = 2 }
  elseif ($bytes.Length -le 65535) { $frame[1] = 0xFE; $frame[2] = [byte](($bytes.Length -shr 8) -band 0xFF); $frame[3] = [byte]($bytes.Length -band 0xFF); $offset = 4 }
  else { $frame[1] = 0xFF; for ($i=0; $i -lt 8; $i++) { $frame[2+$i] = [byte](($bytes.Length -shr (8*(7-$i))) -band 0xFF) }; $offset = 10 }
  for ($i=0; $i -lt 4; $i++) { $frame[$offset+$i] = $maskKey[$i] }
  for ($i=0; $i -lt $bytes.Length; $i++) { $frame[$offset+4+$i] = $bytes[$i] -bxor $maskKey[$i % 4] }
  $segment = [ArraySegment[byte]]::new($frame, 0, $offset + 4 + $bytes.Length)
  $socket.SendAsync($segment, [System.Net.WebSockets.WebSocketMessageType]::Text, $true, [System.Threading.CancellationToken]::None).GetAwaiter().GetResult()
}

function Receive-Until($socket, [int]$id) {
  $buffer = [byte[]]::new(1048576)
  $builder = [System.Text.StringBuilder]::new()
  while ($true) {
    $result = $socket.ReceiveAsync([ArraySegment[byte]]::new($buffer), [System.Threading.CancellationToken]::None).GetAwaiter().GetResult()
    if ($result.MessageType -eq [System.Net.WebSockets.WebSocketMessageType]::Close) { throw 'socket closed' }
    [void]$builder.Append([System.Text.Encoding]::UTF8.GetString($buffer, 0, $result.Count))
    $text = $builder.ToString()
    try {
      $obj = $text | ConvertFrom-Json
      if ($obj.id -eq $id) { return $obj }
    } catch { }
  }
}

