  stepConfig.skills['0'] = oldStep0.filter((id) => !testSkillIds.includes(id))
  await write('wa_pipeline_step_config', stepConfig)

  await window.electronAPI.storageRemove('wa_pipeline_breakpoint')
  if (pipelineStore) {
    pipelineStore.breakpoint = null
    pipelineStore.chapterProgress = null
  }
  if (skillStore?.loadSkills) await skillStore.loadSkills()
  if (projectStore?.saveProject) await projectStore.saveProject()

  const after = {
    removedSkillCount: removed,
    skillCount: (await read('wa_skills'))?.skills?.length || 0,
    remainingTestSkills: ((await read('wa_skills'))?.skills || []).filter((skill) => testSkillIds.includes(skill.id)).length,
    step0Skills: (await read('wa_pipeline_step_config'))?.skills?.['0'] || [],
    breakpoint: await read('wa_pipeline_breakpoint')
  }
  return { before, after }
}, TEST_SKILL_IDS)

