const fs = require("fs");
const path = require("path");
const home = process.env.USERPROFILE;
const extPath = path.join(home, "Documents", "New project 2", "_writerhelper_unpack", "extension", "dist", "extension.js");
const outDir = path.join(home, "Documents", "New project 2", "_writerhelper_analysis");
if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });
const src = fs.readFileSync(extPath, "utf8");

// 1. Extract the wA config object (baseUrl + api endpoints)
const wAStart = src.indexOf("baseUrl:\"https://writer.tanzzj.com\"");
if (wAStart >= 0) {
  // Find the start of the object (look back for "{")
  let start = src.lastIndexOf("wA=", wAStart);
  if (start < 0) start = src.lastIndexOf("{baseUrl:", wAStart);
  if (start < 0) start = wAStart - 100;
  // Find end of object
  let depth = 0;
  let end = wAStart;
  for (let i = wAStart; i < src.length; i++) {
    if (src[i] === "{") depth++;
    if (src[i] === "}") { depth--; if (depth === 0) { end = i + 1; break; } }
  }
  fs.writeFileSync(path.join(outDir, "stage1_wA_config.txt"), src.substring(start, end), "utf8");
  console.log("wA config extracted, length:", end - start);
} else {
  console.log("wA config not found");
}

// 2. Extract RequestUtil class (getBaseUrl, getToken, request, get, post, download, uploadFile)
const ruStart = src.indexOf("static async getBaseUrl");
if (ruStart >= 0) {
  let start = src.lastIndexOf("class ", ruStart);
  if (start < 0 || ruStart - start > 500) start = ruStart - 200;
  // find the class end by tracking class braces
  let depth = 0;
  let foundStart = false;
  let end = start;
  for (let i = start; i < src.length; i++) {
    if (src[i] === "{") { depth++; foundStart = true; }
    if (src[i] === "}") { depth--; if (foundStart && depth === 0) { end = i + 1; break; } }
  }
  fs.writeFileSync(path.join(outDir, "stage1_request_util.txt"), src.substring(start, end), "utf8");
  console.log("RequestUtil extracted, length:", end - start);
} else {
  console.log("RequestUtil not found");
}

// 3. Extract auth/token related code
const tokenPatterns = ["getToken", "auth.token", "tokenCheck", "tokenRefresh", "secrets.get", "secrets.store"];
const tokenResults = [];
let searchFrom = 0;
for (const pat of tokenPatterns) {
  let idx = src.indexOf(pat, searchFrom);
  while (idx >= 0 && tokenResults.length < 100) {
    const lineStart = src.lastIndexOf("\n", idx) + 1;
    const lineEnd = src.indexOf("\n", idx);
    tokenResults.push(src.substring(lineStart, Math.min(lineEnd > 0 ? lineEnd : lineStart + 300, lineStart + 300)));
    idx = src.indexOf(pat, idx + 1);
  }
}
fs.writeFileSync(path.join(outDir, "stage1_auth_tokens.txt"), tokenResults.join("\n---\n"), "utf8");
console.log("Auth token matches:", tokenResults.length);
