const fs = require("fs");
const path = require("path");
const home = process.env.USERPROFILE;
const extPath = path.join(home, "Documents", "New project 2", "_writerhelper_unpack", "extension", "dist", "extension.js");
const outDir = path.join(home, "Documents", "New project 2", "_writerhelper_analysis");
if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });
const src = fs.readFileSync(extPath, "utf8");

// Helper: extract class body by class variable name (e.g. "Gde=class")
function extractClassBody(varName) {
  // Search for pattern like "Gde=class" or "Gde class"
  const patterns = [varName + "=class", varName + " =class", varName + "= class"];
  for (const pat of patterns) {
    const idx = src.indexOf(pat);
    if (idx >= 0) {
      // Find the opening brace of the class body
      let braceStart = src.indexOf("{", idx);
      if (braceStart < 0 || braceStart - idx > 200) continue;
      // Track braces to find the end
      let depth = 0;
      let end = braceStart;
      for (let i = braceStart; i < src.length; i++) {
        if (src[i] === "{") depth++;
        if (src[i] === "}") { depth--; if (depth === 0) { end = i + 1; break; } }
      }
      return { start: idx, end: end, body: src.substring(idx, end) };
    }
  }
  return null;
}

// Known minified class names
const classes = {
  "CharacterManager_Gde": "Gde",
  "ScriptManager_Yde": "Yde",
  "StoryboardManager_qde": "qde",
  "VideoTaskPoller_Ege": "Ege",
};

for (const [label, varName] of Object.entries(classes)) {
  const result = extractClassBody(varName);
  if (result) {
    fs.writeFileSync(path.join(outDir, "stage67_" + label + ".txt"), result.body, "utf8");
    console.log(label + " extracted: " + result.body.length + " chars (pos " + result.start + "-" + result.end + ")");
  } else {
    console.log(label + " NOT FOUND with pattern " + varName + "=class");
  }
}

// Also search for art style / draw style configs
const artStylePatterns = ["drawStyle", "draw_style", "artStyle", "art_style", "画风", "stylePrompt", "style_prompt", "roleDrawStyle", "imageProfile", "image_profile", "videoProfile", "video_profile"];
const artResults = {};
for (const pat of artStylePatterns) {
  const hits = [];
  let idx = 0;
  while ((idx = src.indexOf(pat, idx)) >= 0 && hits.length < 15) {
    const start = Math.max(0, idx - 100);
    const end = Math.min(src.length, idx + 300);
    hits.push(src.substring(start, end));
    idx += pat.length;
